def maybe_mangle_lambdas(agg_spec):
    # assuming agg_spec is a list of tuples
    mangled_spec = []
    for spec in agg_spec:
        if spec[1] == '<lambda>':
            mangled_spec.append((spec[0], 'lambda'))
        else:
            mangled_spec.append(spec)
    return mangled_spec

def _make_unique_kwarg_list(seq):
    unique_kwargs = []
    for kwarg in seq:
        if kwarg not in unique_kwargs:
            unique_kwargs.append(kwarg)
    return unique_kwargs

